INSERT INTO news (date, lang, title, text) VALUES
 ('2026-11-18', 'es', 'LAIKA 64 3.1: en línea más fluido', 'Se acabaron los tirones de medio segundo, siempre se juega en 1280x720 y una pausa de tu consola ya no te saca. Nuevo panel de jugadores con avatar y ping de cada uno, avisos cuando la partida espera y un teclado de chat más rápido: RT envía y doble BACK lo abre.'),
 ('2026-11-18', 'en', 'LAIKA 64 3.1: smoother online play', 'No more half-second freezes, games always run at 1280x720 and a pause of your console no longer drops you. New players panel with each one''s avatar and ping, notices when the game waits and a faster chat keyboard: RT sends and double BACK opens it.'),
 ('2026-11-18', 'pt', 'LAIKA 64 3.1: online mais fluido', 'Acabaram as travadas de meio segundo, sempre se joga em 1280x720 e uma pausa do seu console não te tira mais. Novo painel de jogadores com avatar e ping de cada um, avisos quando a partida espera e um teclado de chat mais rápido: RT envia e BACK duas vezes o abre.'),
 ('2026-11-18', 'fr', 'LAIKA 64 3.1 : en ligne plus fluide', 'Fini les gels d''une demi-seconde, on joue toujours en 1280x720 et une pause de votre console ne vous éjecte plus. Nouveau panneau des joueurs avec l''avatar et le ping de chacun, avis quand la partie attend et un clavier de chat plus rapide : RT envoie, double BACK l''ouvre.'),
 ('2026-11-18', 'it', 'LAIKA 64 3.1: online più fluido', 'Basta blocchi di mezzo secondo, si gioca sempre a 1280x720 e una pausa della tua console non ti butta più fuori. Nuovo pannello giocatori con avatar e ping di ognuno, avvisi quando la partita aspetta e una tastiera della chat più veloce: RT invia e doppio BACK la apre.'),
 ('2026-11-18', 'de', 'LAIKA 64 3.1: flüssiger online', 'Keine halbsekündigen Hänger mehr, immer 1280x720, und eine Pause deiner Konsole wirft dich nicht mehr raus. Neue Spielerliste mit Avatar und Ping von jedem, Hinweise wenn das Spiel wartet und eine schnellere Chat-Tastatur: RT sendet, zweimal BACK öffnet sie.'),
 ('2026-11-18', 'ru', 'LAIKA 64 3.1: онлайн плавнее', 'Больше нет полусекундных зависаний, игра всегда в 1280x720, а пауза вашей консоли больше не выкидывает из игры. Новая панель игроков с аватаром и пингом каждого, уведомления, когда игра ждёт, и быстрая клавиатура чата: RT отправляет, двойной BACK открывает.');
